function main({data1, data2}) {
    // 将时间字符串解析为小时
    const hour1 = parseInt(data1, 10);
    const hour2 = parseInt(data2, 10);

    // 比较小时
    if (hour1 > hour2) {
        return {
            result: 0,
            data2: data2
        };
    } else if (hour1 < hour2) {
        return {
            result: 1,
            data2: data2
        };
    } else {
        // 如果相等，根据需求返回特定值
        return {
            result: 1, // 假设相等时返回1
            data2: data2
        };
    }
}

