function main({ data1 }) {
  // 解析JSON字符串
  const parsedData = typeof data1 === 'string' ? JSON.parse(data1) : data1;
  const { startTime, endTime } = parsedData;

  // 通用时间提取与格式化函数
  const formatTime = (timeValue) => {
    if (!timeValue) return "";

    const timeStr = String(timeValue).trim();

    // 情况1: 提取末尾的 H:M、HH:MM、H:MM、HH:M 等格式（包括带秒的情况）
    const match = timeStr.match(/(\d{1,2}):(\d{1,2})(?::\d{1,2})?$/);
    if (match) {
      let [_, hour, minute] = match;
      // 可选：标准化为两位格式（如 "9:0" → "09:00"）
      hour = hour.padStart(2, '0');
      minute = minute.padStart(2, '0');
      return `${hour}:${minute}`;
    }

    // 如果没有匹配到时间格式，返回空
    return "";
  };

  return {
    result: {
      startTime: formatTime(startTime),
      endTime: formatTime(endTime)
    }
  };
}

