function main({ realDate, data1, data2 }) {
    // 安全提取 realDate 年份和月份
    const realDateObj = new Date(realDate.split(' ')[0]);
    const realYear = realDateObj.getFullYear();
    const realMonth = realDateObj.getMonth(); // JS 月份是 0-11（0=Jan）

    const normalizeDate = (dateStr) => {
        let d = new Date(dateStr + 'T00:00:00');
        if (isNaN(d.getTime())) throw new Error(`Invalid date: ${dateStr}`);

        let year = d.getFullYear();
        let month = d.getMonth(); // 0-11

        // 原逻辑：如果年份 < realYear，修正为 realYear
        if (year < realYear) {
            d.setFullYear(realYear);
            year = realYear;
            // 注意：setFullYear 不会改变 month/day，所以 month 仍有效
            month = d.getMonth();
        }

        // 新增逻辑：如果年份 == realYear，且月份比 realDate 早超过 2 个月
        if (year === realYear) {
            // 计算月份差（realMonth - month），考虑跨年？但年份相同，不用跨年
            const monthDiff = realMonth - month;
            if (monthDiff > 2) {
                // 例如：real 是 12月（11），data 是 9月（8）→ 11-8=3 >2 → 加一年
                d.setFullYear(realYear + 1);
            }
        }

        return d.toLocaleDateString('zh-CN', {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit'
        }).replace(/\//g, '-');
    };

    return {
        data1: normalizeDate(data1),
        data2: normalizeDate(data2)
    };
}

