function main({ data1 }) {
    const shifts = JSON.parse(data1);

    // 从后往前遍历
    for (let i = shifts.length - 1; i >= 0; i--) {
        const shift = shifts[i];
        const code = shift.shiftCode;

        // 跳过无效班次：空、OFF、defaultOFF 开头
        if (
            !code || 
            code === "" || 
            code === "OFF" || 
            (typeof code === 'string' && code.startsWith('defaultOFF'))
        ) {
            continue;
        }

        // 找到第一个有效班次，返回其时间
        return {
            startTime: shift.startTime,
            endTime: shift.endTime
        };
    }

    // 如果没有找到任何有效班次
    return {
        startTime: null,
        endTime: null
    };
}

